  "SELECT issues.*, identity.incarnation AS store_incarnation, CAST(unixepoch() AS INTEGER) AS observed_at, claim.incarnation AS claim_incarnation, claim.actor AS claim_actor, claim.session_id AS claim_session_id, claim.agent_label AS claim_agent_label, claim.generation AS claim_generation, claim.revision AS claim_revision, claim.acquired_at AS claim_acquired_at, claim.changed_at AS claim_changed_at, claim.expires_at AS claim_expires_at, claim.released_at AS claim_released_at, CAST((SELECT COUNT(*) FROM dependencies JOIN issues AS blocker ON blocker.id = dependencies.blocker_id WHERE dependencies.dependent_id = issues.id AND blocker.status <> 'closed') AS INTEGER) AS open_blockers FROM issues CROSS JOIN memory_store_identity AS identity LEFT JOIN issue_claims AS claim ON claim.issue_id = issues.id WHERE identity.singleton = 1 AND issues.tool = :tool AND issues.project = :project AND ((:status IS NULL AND issues.status <> 'closed') OR issues.status = :status) AND (:label IS NULL OR EXISTS (SELECT 1 FROM json_each(issues.labels_json) AS label WHERE label.value = :label)) ORDER BY CASE WHEN :closed = 1 THEN issues.updated_at END DESC, CASE WHEN :closed = 1 THEN issues.sort_key END DESC, CASE WHEN :closed = 0 THEN issues.priority END ASC, CASE WHEN :closed = 0 THEN CASE issues.status WHEN 'in_progress' THEN 0 WHEN 'open' THEN 1 WHEN 'deferred' THEN 2 ELSE 3 END END ASC, CASE WHEN :closed = 0 THEN issues.sort_key END ASC LIMIT :limit": { params: ["tool", "project", "status", "label", "closed", "limit"], encode: [], json: [], reads: ["dependencies", "issue_claims", "issues", "memory_store_identity"] },
  "SELECT issues.* FROM issues WHERE tool = :tool AND project = :project AND status = 'closed' ORDER BY updated_at DESC, sort_key DESC LIMIT :limit": { params: ["tool", "project", "limit"], encode: [], json: [], reads: ["issues"] },
  "SELECT issues.* FROM issues WHERE status <> 'closed' AND EXISTS (SELECT 1 FROM json_each(issues.labels_json) AS label WHERE label.value = 'owner-decision' OR label.value = 'owner-action' OR label.value = 'main-wait') ORDER BY updated_at DESC, sort_key DESC LIMIT :limit": { params: ["limit"], encode: [], json: [], reads: ["issues"] },
  "SELECT issues.*, identity.incarnation AS store_incarnation, CAST(unixepoch() AS INTEGER) AS observed_at, claim.incarnation AS claim_incarnation, claim.actor AS claim_actor, claim.session_id AS claim_session_id, claim.agent_label AS claim_agent_label, claim.generation AS claim_generation, claim.revision AS claim_revision, claim.acquired_at AS claim_acquired_at, claim.changed_at AS claim_changed_at, claim.expires_at AS claim_expires_at, claim.released_at AS claim_released_at FROM issues CROSS JOIN memory_store_identity AS identity JOIN issue_claims AS claim ON claim.issue_id = issues.id WHERE identity.singleton = 1 AND claim.released_at IS NULL AND claim.expires_at > unixepoch() AND claim.incarnation = identity.incarnation ORDER BY claim.expires_at ASC, issues.sort_key ASC LIMIT :limit": { params: ["limit"], encode: [], json: [], reads: ["issue_claims", "issues", "memory_store_identity"] },
